import{_ as e,o as A,c as o,ak as n}from"./chunks/framework.DC5fGio6.js";const i="data:image/png;base64,",r="/projects/MaxArm/en/latest/assets/image3.BW7DwOkG.png",a="data:image/png;base64,",l="/projects/MaxArm/en/latest/assets/image5.D-IiPVB5.jpeg",s="/projects/MaxArm/en/latest/assets/image6.CEvCgXVl.jpeg",c="/projects/MaxArm/en/latest/assets/image7.CKRAHt1o.png",p="/projects/MaxArm/en/latest/assets/image8.DD1RDtUA.png",d="/projects/MaxArm/en/latest/assets/image9.7e7VVspx.png",g="data:image/png;base64,",h="data:image/png;base64,",m="data:image/png;base64,",f="data:image/jpeg;base64,",u="/projects/MaxArm/en/latest/assets/image14.Cq-1RKCF.png",w="/projects/MaxArm/en/latest/assets/image15.DM51s9kK.png",R="/projects/MaxArm/en/latest/assets/image16.BD9Wlt1m.png",U="/projects/MaxArm/en/latest/assets/image17.CznHI_ru.png",P="/projects/MaxArm/en/latest/assets/image18.D2a-Bkca.jpeg",x="/projects/MaxArm/en/latest/assets/image19.Bm6Dgvmj.jpeg",B="/projects/MaxArm/en/latest/assets/image20.DxR7NFsu.jpeg",Q="data:image/jpeg;base64,",y="data:image/jpeg;base64,",F="/projects/MaxArm/en/latest/assets/image2.CsPqOsaU.png",q=JSON.parse('{"title":"2. Remote Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2.Remote_Control_formatted.md","filePath":"docs/2.Remote_Control_formatted.md"}'),K={name:"docs/2.Remote_Control_formatted.md"};function b(D,t,v,E,j,C){return A(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="_2-remote-control" tabindex="-1">2. Remote Control <a class="header-anchor" href="#_2-remote-control" aria-label="Permalink to &quot;2. Remote Control&quot;">​</a></h1><h2 id="_2-1-app-control" tabindex="-1">2.1 APP Control <a class="header-anchor" href="#_2-1-app-control" aria-label="Permalink to &quot;2.1 APP Control&quot;">​</a></h2><h3 id="_2-1-1-app-installation" tabindex="-1">2.1.1 App Installation <a class="header-anchor" href="#_2-1-1-app-installation" aria-label="Permalink to &quot;2.1.1 App Installation&quot;">​</a></h3><p>Android user: you can find the installation package under the same directory and transfer it to your phone to install.</p><img loading="lazy" height="30" width="300" src="'+i+'" class="common_img"><p>iOS user: please download and install <strong>&quot;<a href="https://apps.apple.com/us/app/wonderbot-robot/id1519146341" target="_blank" rel="noreferrer">Wonderbot Robot</a>&quot;</strong> in App Store.</p><h3 id="_2-1-2-device-connection" tabindex="-1">2.1.2 Device Connection <a class="header-anchor" href="#_2-1-2-device-connection" aria-label="Permalink to &quot;2.1.2 Device Connection&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li>Please enable Bluetooth and GPS services in your phone settings before using app.</li><li>Please use the Bluetooth button in app to pair and connect with the device.</li><li>Android user must enable all permissions for app in phone settings, otherwise it may affect the function implementation!</li><li>This lesson takes Android system as example. The requirement for system version: Android 5.0 and above, iOS9.0 and above.</li></ul></div><ul><li><strong>Turn on MaxArm and open &quot;Wonderbot&quot;. The app main interface is shown in figure below:</strong></li></ul><img loading="lazy" height="586" width="1269" src="'+r+'" class="common_img"><p>(1) If the main interface does not show up, please click on <img loading="lazy" height="69" width="69" src="'+a+'"> icon and click <strong>&quot;Robot&quot;</strong> to select MaxArm.</p><img loading="lazy" height="474" width="1008" src="'+l+'" class="common_img"><p>(2) Click on the flashing Bluetooth icon in the main interface to enter device searching status.</p><img loading="lazy" height="79" width="1189" src="'+s+'" class="common_img"><p>(3) Wait for a moment, then select <strong>&quot;MaxArm&quot;</strong>.</p><img loading="lazy" height="1170" width="2532" src="'+c+'" class="common_img"><p>(4) When the Bluetooth icon stops flashing and keeps on, and the prompt <strong>&quot;Bluetooth is connected&quot;</strong> appears, which means robot has been connected successfully.</p><img loading="lazy" height="1170" width="2532" src="'+p+'" class="common_img"><h3 id="_2-1-3-button-instruction" tabindex="-1">2.1.3 Button Instruction <a class="header-anchor" href="#_2-1-3-button-instruction" aria-label="Permalink to &quot;2.1.3 Button Instruction&quot;">​</a></h3><p>The app interface consists of four parts, which are menu bar, end effector coordinate control area, action calling area, suction nozzle control area.</p><img loading="lazy" height="1170" width="2532" src="'+d+'" class="common_img"><ul><li><strong>Menu Bar</strong></li></ul><table class="docutils-nobg" border="1"><colgroup><col style="width:51%;"><col style="width:48%;"></colgroup><tbody><tr><td style="text-align:center;">Icon</td><td style="text-align:center;">Function</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="73" width="101" src="'+g+'"></td><td style="text-align:left;"><p>Product selection button</p><p>Click to select corresponding robot</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="71" width="83" src="'+h+'"></td><td style="text-align:left;"><p>Bluetooth connection button</p><p>If icon keeps flashing, Bluetooth is not connected.</p><p>If icon keeps on, Bluetooth is connected.</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="61" width="78" src="'+m+'"></td><td style="text-align:left;"><p>Help button</p><p>Click on it to check Hiwonder e-mail address and official website.</p></td></tr></tbody></table><p>(1) End Effector Coordinate Control Area</p><p>The left and right sides of the main interface are the <strong>&quot;End Effector coordinate control&quot;</strong> area. Click the corresponding button to control robotic arm to move up and down, left and right, forward and backward. (Long press button for quick movement while short press for slight adjustment. When the robotic arm moves to the limited position, buzzer will alarm. After clicking <strong>&quot;reset&quot;</strong> button, buzzer will make sound and robotic arm will return to the initial position.)</p><table class="docutils-nobg" border="1"><colgroup><col style="width:51%;"><col style="width:48%;"></colgroup><tbody><tr><td style="text-align:center;">Icon</td><td style="text-align:center;">Function</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="83" width="89" src="'+f+'"></td><td style="text-align:center;">Control robotic arm to return to the initial posture</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="193" width="115" src="'+u+'"></td><td style="text-align:center;"><p>Increase the value of x-axis</p><p>MaxArm rotates horizontally to the left</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="194" width="111" src="'+w+'"></td><td style="text-align:center;"><p>Decrease the value of x-axis</p><p>MaxArm rotates horizontally to the right</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="114" width="200" src="'+R+'"></td><td style="text-align:center;"><p>Increase the value of y-axis</p><p>MaxArm rotates backward</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="116" width="198" src="'+U+'"></td><td style="text-align:center;"><p>Decrease the value of y-axis</p><p>MaxArm rotates forward</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="330" width="94" src="'+P+'" style="width:70px;"></td><td style="text-align:center;"><p>Up: control the robotic arm to move up</p><p>Down: control the robotic arm to move down</p></td></tr></tbody></table><p>(2) Action Calling Area</p><p>The upper middle part of interface is <strong>&quot;action group&quot;</strong> area. Click on it to call the action group files downloaded to the robotic arm.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Icon</th><th style="text-align:center;">Function</th></tr></thead><tbody><tr><td style="text-align:center;"><img loading="lazy" height="146" width="177" src="'+x+'"></td><td style="text-align:center;">Run the custom action group file</td></tr></tbody></table><p>(3) Suction Nozzle Control Area</p><p>The lower part of interface is <strong>&quot;suction nozzle control&quot;</strong> area. Click on it to control the rotation and status of suction nozzle.</p><table class="docutils-nobg" border="1"><colgroup><col style="width:51%;"><col style="width:48%;"></colgroup><tbody><tr><td style="text-align:center;">Icon</td><td style="text-align:center;">Function</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="113" width="515" src="'+B+'" style="width:300px;"></td><td style="text-align:left;"><p>Clockwise: suction nozzle rotates clockwise</p><p>Anti-clockwise:suction nozzle rotates counterclockwise</p></td></tr><tr><td style="text-align:center;"><img loading="lazy" height="107" width="223" src="'+Q+'"></td><td style="text-align:left;">The air pump starts pumping</td></tr><tr><td style="text-align:center;"><img loading="lazy" height="107" width="219" src="'+y+'"></td><td style="text-align:left;">The air pump stops pumping</td></tr></tbody></table><h2 id="_2-2-mouse-control" tabindex="-1">2.2 Mouse Control <a class="header-anchor" href="#_2-2-mouse-control" aria-label="Permalink to &quot;2.2 Mouse Control&quot;">​</a></h2><h3 id="_2-2-1-preparation" tabindex="-1">2.2.1 Preparation <a class="header-anchor" href="#_2-2-1-preparation" aria-label="Permalink to &quot;2.2.1 Preparation&quot;">​</a></h3><ul><li><strong>Refer to <a href="./1.Getting_Ready_checked.html#first-start-maxarm">1.Getting Ready-&gt;Lesson 2 Start MaxArm</a> to turn on robot arm.</strong></li></ul><p>(1) Please prepare a mouse (wired or wireless). Connect mouse cable to USB port on expansion board, as shown in the figure below:</p><img loading="lazy" height="565" width="847" src="'+F+'" class="common_img"><h3 id="_2-2-2-operation-instruction" tabindex="-1">2.2.2 Operation Instruction <a class="header-anchor" href="#_2-2-2-operation-instruction" aria-label="Permalink to &quot;2.2.2 Operation Instruction&quot;">​</a></h3><p>The operation instruction is shown in the following table:</p><table class="docutils-nobg" border="1"><colgroup><col style="width:50%;"><col style="width:50%;"></colgroup><tbody><tr><td style="text-align:center;"><strong>Operation</strong></td><td style="text-align:center;"><strong>Outcome</strong></td></tr><tr><td style="text-align:center;">Move mouse in any directions</td><td style="text-align:center;">The suction nozzle moves with the mouse</td></tr><tr><td style="text-align:center;">Press left mouse button + move left and right</td><td style="text-align:center;">The suction nozzle rotates counterclockwise or clockwise</td></tr><tr><td style="text-align:center;">Scroll mouse wheel up and down</td><td style="text-align:center;">The suction nozzle moves up and down along z-axis</td></tr><tr><td style="text-align:center;">Press right mouse button + move in any directions</td><td style="text-align:center;"><p>The air pump starts to pumping</p><p>(Right-click mouse to stop pumping)</p></td></tr></tbody></table>',40)])])}const O=e(K,[["render",b]]);export{q as __pageData,O as default};
